CREATE TABLE identifier_before_tasks AS SELECT * FROM tasks;
CREATE TABLE identifier_before_private_work AS SELECT * FROM private_work;
CREATE TABLE identifier_verification(check_name TEXT PRIMARY KEY,record_count INTEGER NOT NULL,verified INTEGER NOT NULL CHECK(verified=1));
-- Additive only; original identifiers, workflow fields and records remain untouched.
CREATE TABLE task_numbers(number INTEGER PRIMARY KEY AUTOINCREMENT,entity TEXT NOT NULL CHECK(entity IN ('shared','private')),entity_id TEXT NOT NULL,UNIQUE(entity,entity_id));
ALTER TABLE tasks ADD COLUMN task_code TEXT NOT NULL DEFAULT '';
ALTER TABLE private_work ADD COLUMN task_code TEXT NOT NULL DEFAULT '';
INSERT INTO task_numbers(entity,entity_id) SELECT entity,entity_id FROM (SELECT 'shared' entity,id entity_id,created_at FROM tasks UNION ALL SELECT 'private',id,created_at FROM private_work WHERE kind='Task') ORDER BY created_at,entity,entity_id;
UPDATE tasks SET task_code=(SELECT printf('WT-%06d',number) FROM task_numbers WHERE entity='shared' AND entity_id=tasks.id);
UPDATE private_work SET task_code=(SELECT printf('WT-%06d',number) FROM task_numbers WHERE entity='private' AND entity_id=private_work.id) WHERE kind='Task';
CREATE UNIQUE INDEX tasks_code_unique ON tasks(task_code) WHERE task_code<>'';
CREATE UNIQUE INDEX private_work_code_unique ON private_work(task_code) WHERE task_code<>'';
CREATE TRIGGER task_number_on_create AFTER INSERT ON tasks BEGIN
 INSERT INTO task_numbers(entity,entity_id) VALUES('shared',NEW.id);
 UPDATE tasks SET task_code=(SELECT printf('WT-%06d',number) FROM task_numbers WHERE entity='shared' AND entity_id=NEW.id) WHERE id=NEW.id;
END;
CREATE TRIGGER private_task_number_on_create AFTER INSERT ON private_work WHEN NEW.kind='Task' BEGIN
 INSERT INTO task_numbers(entity,entity_id) VALUES('private',NEW.id);
 UPDATE private_work SET task_code=(SELECT printf('WT-%06d',number) FROM task_numbers WHERE entity='private' AND entity_id=NEW.id) WHERE id=NEW.id;
END;
CREATE TRIGGER tasks_code_immutable BEFORE UPDATE OF task_code ON tasks WHEN OLD.task_code<>'' AND NEW.task_code<>OLD.task_code BEGIN SELECT RAISE(ABORT,'Task ID is permanent'); END;
CREATE TRIGGER private_code_immutable BEFORE UPDATE OF task_code ON private_work WHEN OLD.task_code<>'' AND NEW.task_code<>OLD.task_code BEGIN SELECT RAISE(ABORT,'Task ID is permanent'); END;
CREATE TRIGGER task_numbers_no_update BEFORE UPDATE ON task_numbers BEGIN SELECT RAISE(ABORT,'Task numbers are permanent'); END;
CREATE TRIGGER task_numbers_no_delete BEFORE DELETE ON task_numbers BEGIN SELECT RAISE(ABORT,'Task numbers are permanent'); END;
CREATE TABLE task_urgency(task_id TEXT PRIMARY KEY REFERENCES tasks(id),cycle INTEGER NOT NULL DEFAULT 1,action_revision INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)),marked_by TEXT NOT NULL,marked_at TEXT NOT NULL,cancelled_by TEXT NOT NULL DEFAULT '',cancelled_at TEXT NOT NULL DEFAULT '',event_token TEXT NOT NULL);
CREATE TABLE urgent_acknowledgements(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),cycle INTEGER NOT NULL,recipient_email TEXT NOT NULL,action_key TEXT NOT NULL,acknowledged_at TEXT NOT NULL,UNIQUE(task_id,cycle,recipient_email,action_key));
CREATE TABLE urgent_events(id TEXT PRIMARY KEY,task_id TEXT NOT NULL REFERENCES tasks(id),cycle INTEGER NOT NULL,action TEXT NOT NULL CHECK(action IN('Marked as Urgent','Cancelled Urgent','Acknowledged Reminder')),actor_email TEXT NOT NULL,recorded_at TEXT NOT NULL);
CREATE INDEX urgent_events_task ON urgent_events(task_id,recorded_at);
CREATE INDEX urgency_active ON task_urgency(active,task_id);
CREATE TRIGGER urgent_events_no_update BEFORE UPDATE ON urgent_events BEGIN SELECT RAISE(ABORT,'Urgent history is immutable'); END;
CREATE TRIGGER urgent_events_no_delete BEFORE DELETE ON urgent_events BEGIN SELECT RAISE(ABORT,'Urgent history is immutable'); END;
CREATE TRIGGER urgent_ack_no_update BEFORE UPDATE ON urgent_acknowledgements BEGIN SELECT RAISE(ABORT,'Urgent acknowledgements are immutable'); END;
CREATE TRIGGER urgent_ack_no_delete BEFORE DELETE ON urgent_acknowledgements BEGIN SELECT RAISE(ABORT,'Urgent acknowledgements are immutable'); END;

INSERT INTO identifier_verification VALUES('tasks_original_fields_unchanged',(SELECT count(*) FROM tasks),CASE WHEN NOT EXISTS(SELECT "id","title","description","type","priority","sort_order","development_status","qa_status","assignee","next_action_owner","project","github_pr_url","created_by","created_at","updated_at","archived","category","parent_task_id","next_step","deleted","current_environment","feasibility","estimated_delivery_date","qa_owner","review_notes","stage_confirmed_at","qa_passed_stage_at","workflow_revision","completed_date","work_kind","work_status","work_category","planning_status","primary_owner","collaborators_json","original_delivery_date","engineering_completed_date","qa_due_date","qa_completed_date","delivery_reset_required","blocked_reason","follow_up_date","pm_owner","pm_stage","pm_engineer","pm_solution","pm_resume_stage","pm_resume_owner","pm_request_comment","pm_transition_token","production_completed_date","pr_submitted_date","pr_review_completed_date","pr_reviewer","pr_review_merged_at","pr_review_confirmed_by" FROM tasks EXCEPT SELECT * FROM identifier_before_tasks) AND NOT EXISTS(SELECT * FROM identifier_before_tasks EXCEPT SELECT "id","title","description","type","priority","sort_order","development_status","qa_status","assignee","next_action_owner","project","github_pr_url","created_by","created_at","updated_at","archived","category","parent_task_id","next_step","deleted","current_environment","feasibility","estimated_delivery_date","qa_owner","review_notes","stage_confirmed_at","qa_passed_stage_at","workflow_revision","completed_date","work_kind","work_status","work_category","planning_status","primary_owner","collaborators_json","original_delivery_date","engineering_completed_date","qa_due_date","qa_completed_date","delivery_reset_required","blocked_reason","follow_up_date","pm_owner","pm_stage","pm_engineer","pm_solution","pm_resume_stage","pm_resume_owner","pm_request_comment","pm_transition_token","production_completed_date","pr_submitted_date","pr_review_completed_date","pr_reviewer","pr_review_merged_at","pr_review_confirmed_by" FROM tasks) THEN 1 ELSE 0 END);
INSERT INTO identifier_verification VALUES('private_work_original_fields_unchanged',(SELECT count(*) FROM private_work),CASE WHEN NOT EXISTS(SELECT "id","owner_email","kind","title","description","parent_id","status","deleted","created_at","updated_at","recurrence_rule","next_due_date","recurrence_anchor_day","archived","completed_date" FROM private_work EXCEPT SELECT * FROM identifier_before_private_work) AND NOT EXISTS(SELECT * FROM identifier_before_private_work EXCEPT SELECT "id","owner_email","kind","title","description","parent_id","status","deleted","created_at","updated_at","recurrence_rule","next_due_date","recurrence_anchor_day","archived","completed_date" FROM private_work) THEN 1 ELSE 0 END);
INSERT INTO identifier_verification VALUES('shared_codes_assigned',(SELECT count(*) FROM tasks),CASE WHEN NOT EXISTS(SELECT 1 FROM tasks WHERE task_code='' OR task_code IS NULL) THEN 1 ELSE 0 END);
INSERT INTO identifier_verification VALUES('private_task_codes_assigned',(SELECT count(*) FROM private_work WHERE kind='Task'),CASE WHEN NOT EXISTS(SELECT 1 FROM private_work WHERE kind='Task' AND (task_code='' OR task_code IS NULL)) THEN 1 ELSE 0 END);
INSERT INTO identifier_verification VALUES('global_codes_unique',(SELECT count(*) FROM task_numbers),CASE WHEN (SELECT count(*) FROM task_numbers)=(SELECT count(*) FROM tasks)+(SELECT count(*) FROM private_work WHERE kind='Task') AND NOT EXISTS(SELECT task_code FROM (SELECT task_code FROM tasks UNION ALL SELECT task_code FROM private_work WHERE kind='Task') GROUP BY task_code HAVING count(*)>1) THEN 1 ELSE 0 END);

CREATE TRIGGER urgent_current_action_changed AFTER UPDATE ON tasks WHEN NEW.development_status<>OLD.development_status OR NEW.qa_status<>OLD.qa_status OR NEW.work_status<>OLD.work_status OR NEW.pm_stage<>OLD.pm_stage OR NEW.assignee<>OLD.assignee OR NEW.primary_owner<>OLD.primary_owner OR NEW.qa_owner<>OLD.qa_owner OR NEW.next_action_owner<>OLD.next_action_owner OR NEW.pr_reviewer<>OLD.pr_reviewer OR NEW.planning_status<>OLD.planning_status OR NEW.stage_confirmed_at<>OLD.stage_confirmed_at OR NEW.pr_review_merged_at<>OLD.pr_review_merged_at BEGIN UPDATE task_urgency SET action_revision=action_revision+1 WHERE task_id=NEW.id AND active=1; END;
